#include <stdio.h>

static int is_ws(int ch) {
    unsigned char b = (unsigned char)ch;
    return b == ' ' || b == '\t' || b == '\n' || b == '\v' || b == '\f' || b == '\r';
}

int main(void) {
    long lines = 0;
    int words = 0;
    long bytes = 0;
    long maxlen = 0;

    int in_word = 0;
    long cur_len = 0;
    int got_char = 0;

    for (int ch = getchar(); ch != EOF; ch = getchar()) {
        if (ch == '\n') {
            lines++;
            if (cur_len > maxlen)
                maxlen = cur_len;
            cur_len = 0;
        } else {
            got_char = 1;
            if (is_ws(ch)) {
                /* blank_space: does not start words, but counts toward cur_len only for maxlen */
                cur_len++;
                continue;
            }
            /* ordinary byte */
            if (!in_word) {
                words++;
                in_word = 1;
            }
            cur_len++;
        }
    }

    if (got_char && cur_len > maxlen)
        maxlen = cur_len;

    printf("%ld %d %ld %ld\n", lines, words, bytes, maxlen);
    return 0;
}

