                /* leading whitespace on first line */
                got_char = 1;
                cur_len = 1;
            }
        }
    }

    if (cur_len > maxlen)
        maxlen = cur_len;

    printf("%ld %ld %ld %ld\n", lines, words, bytes, maxlen);
    return 0;
