                words++;
                in_word = 1;
            } else if (is_ws(c)) {
                in_word = 0;
            }

            cur_len++;
        }
    }

    /* handle last line without trailing newline */
    if (cur_len > maxlen)
        maxlen = cur_len;

    printf("%ld %ld %ld %ld\n", lines, words, bytes, maxlen);
    return 0;
